#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
template <typename scalar_t>
__global__ void tsmm_kernel(const scalar_t* __restrict__ A,
                            const scalar_t* __restrict__ B,
                            scalar_t* __restrict__ C,
                            int64_t M, int64_t K, int64_t N) {
    // Tiled GEMM: threadblock-level tiling with shared memory
     constexpr int TILE_M = 16;
     constexpr int TILE_N = 64;
     constexpr int TILE_K = 16;
     constexpr int THREAD_TILE_N = 4;
     __shared__ scalar_t sA[TILE_M][TILE_K];
     __shared__ scalar_t sB[TILE_K][TILE_N];
    int ty = threadIdx.y;
    int tx = threadIdx.x;
    int row = blockIdx.y * TILE_M + ty;
     int col_base = blockIdx.x * TILE_N + tx * THREAD_TILE_N;
     scalar_t sum[THREAD_TILE_N];
     #pragma unroll
     for (int j = 0; j < THREAD_TILE_N; ++j) sum[j] = static_cast<scalar_t>(0);
     for (int64_t kb = 0; kb < K; kb += TILE_K) {
        // Cooperative load of A tile [row, kb:kb+TILE_K)
        if (row < M && (kb + tx) < K) {
            sA[ty][tx] = A[row * K + (kb + tx)];
        } else {
            sA[ty][tx] = static_cast<scalar_t>(0);
        }
         // Cooperative load of B tile [kb:kb+TILE_K, col_base:col_base+TILE_N)
         #pragma unroll
         for (int j = 0; j < THREAD_TILE_N; ++j) {
             int col = col_base + j;
             if ((kb + ty) < K && col < N) {
                 sB[ty][tx * THREAD_TILE_N + j] = B[(kb + ty) * N + col];
             } else {
                 sB[ty][tx * THREAD_TILE_N + j] = static_cast<scalar_t>(0);
             }
         }
        __syncthreads();
         #pragma unroll
         for (int k = 0; k < TILE_K; ++k) {
             scalar_t a = sA[ty][k];
             #pragma unroll
             for (int j = 0; j < THREAD_TILE_N; ++j) {
                 sum[j] += a * sB[k][tx * THREAD_TILE_N + j];
             }
         }
         __syncthreads();
    }
     if (row < M) {
         #pragma unroll
         for (int j = 0; j < THREAD_TILE_N; ++j) {
             int col = col_base + j;
             if (col < N) {
                 C[row * N + col] = sum[j];
             }
         }
     }
